// Lista blanca: cada consulta permitida corresponde a UNA herramienta del
// servidor MCP. Cualquier otra consulta se rechaza sin llamar al servidor.
const PERMITIDAS = {
  historial: 'consultar_historial',
  historial_asignaturas: 'consultar_historial',
  progreso: 'consultar_progreso',
  recomendaciones: 'obtener_recomendaciones',
  requisitos: 'obtener_requisitos',
  cursos_disponibles: 'consultar_cursos_disponibles',
};

const entrada = $input.first().json;
const consulta = String(entrada.consulta ?? '').toLowerCase().trim();
const texto = (valor) => {
  const limpio = String(valor ?? '').trim();
  return limpio && !['null', 'ninguno', 'todos', 'undefined'].includes(limpio.toLowerCase())
    ? limpio.slice(0, 80)
    : null;
};

return [{
  json: {
    token_sesion: String(entrada.token_sesion ?? '').trim(),
    consulta,
    herramienta: PERMITIDAS[consulta] ?? null,
    pilar: texto(entrada.pilar),
    curso: texto(entrada.curso),
  },
}];

// El token ya pasó la verificación de firma y vencimiento (nodo JWT).
// Aquí se comprueban emisor, audiencia y código, y se arma la llamada MCP.
const EMISOR = 'chatbot-unab-api';
const AUDIENCIA = 'chatbot-unab';

const claims = $input.first().json.payload ?? {};
const p = $('Normalizar parámetros').first().json;

const audienciaValida = Array.isArray(claims.aud) ? claims.aud.includes(AUDIENCIA) : claims.aud === AUDIENCIA;
if (claims.iss !== EMISOR || !audienciaValida || !/^U00\d{6}$/.test(claims.sub ?? '')) {
  return [{ json: { permitido: false, error: 'No se pudo verificar la identidad del estudiante.' } }];
}
if (!p.herramienta) {
  return [{
    json: {
      permitido: false,
      error: `Consulta no permitida: "${p.consulta}". Usa historial, historial_asignaturas, progreso, recomendaciones, requisitos o cursos_disponibles.`,
    },
  }];
}
if (p.consulta === 'requisitos' && !p.curso) {
  return [{ json: { permitido: false, error: 'Para consultar requisitos indica el nombre o código del curso.' } }];
}

const conPilar = p.pilar ? { pilar: p.pilar } : {};
const argumentos = {
  historial: { token_sesion: p.token_sesion, tipo: 'competencia_digital' },
  historial_asignaturas: { token_sesion: p.token_sesion, tipo: 'asignatura' },
  progreso: { token_sesion: p.token_sesion },
  recomendaciones: { token_sesion: p.token_sesion, ...conPilar },
  requisitos: { curso: p.curso, token_sesion: p.token_sesion },
  cursos_disponibles: { ...conPilar, incluir_asignaturas: false },
}[p.consulta];

return [{
  json: {
    permitido: true,
    estudiante: claims.sub,
    consulta: p.consulta,
    herramienta: p.herramienta,
    argumentos,
  },
}];

// Entrega al agente solo los datos de la herramienta, sin el token
const respuesta = $input.first().json;
const llamada = $('Preparar llamada MCP').first().json;

if (respuesta.error) {
  const detalle = String(respuesta.error.message ?? respuesta.error);
  return [{
    json: {
      consulta: llamada.consulta,
      error: /venci/i.test(detalle)
        ? 'La sesión del estudiante venció. Debe iniciar sesión de nuevo.'
        : 'El servidor de datos académicos no pudo responder esta consulta.',
    },
  }];
}

const texto = (respuesta.content ?? []).find((c) => c.type === 'text')?.text;
const datos = respuesta.structuredContent?.result ?? respuesta.structuredContent ?? texto ?? null;

return [{ json: { consulta: llamada.consulta, herramienta_mcp: llamada.herramienta, datos } }];
